//! The face: the built web board, embedded in the binary (or read from `EYE_FACE_DIR`), and the
//! installable-app manifest.

use super::{AppState, Shared};
use axum::extract::State;
use axum::http::{header, StatusCode};
use axum::response::{IntoResponse, Response};
use serde_json::json;

pub(super) const NO_FACE_HTML: &str = "<!doctype html><meta charset=utf-8><title>eye</title>\
<p>The board was not built into this binary. Run <code>npm run build</code> in <code>face/</code> and rebuild.</p>";

// The built face (face/dist), generated by build.rs; empty when the face was not built.
include!(concat!(env!("OUT_DIR"), "/face_files.rs"));

pub(super) const FACE_CSP: &str =
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; \
img-src 'self' data:; font-src 'self' data:; connect-src 'self'; object-src 'none'; \
base-uri 'none'; form-action 'self'; frame-ancestors 'none'";

// ---------- face (static files) ----------

pub(super) fn mime_of(path: &str) -> &'static str {
    match path.rsplit('.').next().unwrap_or("") {
        "html" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json",
        "webmanifest" => "application/manifest+json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "ico" => "image/x-icon",
        "woff2" => "font/woff2",
        "woff" => "font/woff",
        "txt" => "text/plain; charset=utf-8",
        _ => "application/octet-stream",
    }
}

/// Bytes of one face file, from `EYE_FACE_DIR` when set, else from the embedded table.
pub(super) fn face_file(st: &AppState, name: &str) -> Option<Vec<u8>> {
    if name.is_empty()
        || name
            .split('/')
            .any(|p| p.is_empty() || p == "." || p == ".." || p.contains('\\'))
    {
        return None;
    }
    match &st.face_dir {
        Some(dir) => std::fs::read(dir.join(name)).ok(),
        None => FACE_FILES
            .iter()
            .find(|(n, _)| *n == name)
            .map(|(_, b)| b.to_vec()),
    }
}

pub(super) fn face_response(name: &str, body: Vec<u8>) -> Response {
    let cache = if name == "index.html" {
        "no-cache"
    } else if name.starts_with("assets/") {
        "public, max-age=31536000, immutable"
    } else {
        "no-cache"
    };
    (
        [
            (header::CONTENT_TYPE, mime_of(name)),
            (header::CACHE_CONTROL, cache),
            (header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
            (header::CONTENT_SECURITY_POLICY, FACE_CSP),
        ],
        body,
    )
        .into_response()
}

/// `/`: the face when there is one, else a plain notice.
pub(super) async fn face_index(State(st): State<Shared>) -> Response {
    match face_file(&st, "index.html") {
        Some(body) => face_response("index.html", body),
        None => static_page("text/html; charset=utf-8", NO_FACE_HTML),
    }
}

/// The installable-app description. It needs the token like every page, and its start URL carries
/// the token, so the installed app logs itself in on every launch even after the cookie is gone.
pub(super) async fn app_manifest(State(st): State<Shared>) -> Response {
    let body = json!({
        "name": "agent-eye",
        "short_name": "eye",
        "description": "Where each coding-agent session stands and what is waiting on you.",
        "start_url": format!("/?t={}", st.token),
        "scope": "/",
        "display": "standalone",
        "background_color": "#f2efe6",
        "theme_color": "#161616",
        "icons": [
            {"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png"},
            {"src": "/favicon.svg", "sizes": "any", "type": "image/svg+xml"}
        ]
    });
    (
        [
            (header::CONTENT_TYPE, "application/manifest+json"),
            (header::CACHE_CONTROL, "no-store"),
        ],
        body.to_string(),
    )
        .into_response()
}

/// `/assets/*` and other files of the face. Unknown paths are a plain 404.
pub(super) async fn face_asset(State(st): State<Shared>, uri: axum::http::Uri) -> Response {
    let name = uri.path().trim_start_matches('/');
    match face_file(&st, name) {
        Some(body) => face_response(name, body),
        None => (StatusCode::NOT_FOUND, "not found").into_response(),
    }
}

pub(super) fn static_page(ct: &'static str, body: &'static str) -> Response {
    (
        [
            (header::CONTENT_TYPE, ct),
            (header::CACHE_CONTROL, "no-store"),
            (header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
        ],
        body,
    )
        .into_response()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::server::test_support::*;
    use axum::body::Body;
    use axum::extract::Request;
    use serde_json::Value;

    #[tokio::test]
    async fn face_served_from_eye_face_dir() {
        let d = face_dir();
        let e = env_face(Some(d.path().to_path_buf()));
        let (st, h, body) = raw(&e, req("GET", "/", None)).await;
        assert_eq!(st, StatusCode::OK);
        assert!(body.contains("<title>face</title>"));
        assert_eq!(h[header::CACHE_CONTROL], "no-cache");
        assert!(h[header::CONTENT_TYPE]
            .to_str()
            .unwrap()
            .starts_with("text/html"));

        let (st, h, body) = raw(&e, req("GET", "/assets/app-abc123.js", None)).await;
        assert_eq!(st, StatusCode::OK);
        assert_eq!(body, "console.log(1)");
        assert!(h[header::CONTENT_TYPE]
            .to_str()
            .unwrap()
            .starts_with("text/javascript"));
        assert_eq!(
            h[header::CACHE_CONTROL],
            "public, max-age=31536000, immutable"
        );
        let (_, h, _) = raw(&e, req("GET", "/assets/app-abc123.css", None)).await;
        assert!(h[header::CONTENT_TYPE]
            .to_str()
            .unwrap()
            .starts_with("text/css"));

        let (st, _, _) = raw(&e, req("GET", "/assets/missing.js", None)).await;
        assert_eq!(st, StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn face_files_are_read_per_request() {
        let d = face_dir();
        let e = env_face(Some(d.path().to_path_buf()));
        std::fs::write(d.path().join("index.html"), "second build").unwrap();
        let (_, _, body) = raw(&e, req("GET", "/", None)).await;
        assert_eq!(body, "second build");
    }

    #[tokio::test]
    async fn face_csp_allows_only_self_data_and_inline_styles() {
        let d = face_dir();
        let e = env_face(Some(d.path().to_path_buf()));
        for uri in ["/", "/assets/app-abc123.js"] {
            let (_, h, _) = raw(&e, req("GET", uri, None)).await;
            let csp = h[header::CONTENT_SECURITY_POLICY].to_str().unwrap();
            assert!(csp.contains("default-src 'self'"));
            assert!(csp.contains("script-src 'self';"));
            assert!(csp.contains("style-src 'self' 'unsafe-inline'"));
            assert!(csp.contains("img-src 'self' data:"));
            assert!(csp.contains("font-src 'self' data:"));
            assert!(csp.contains("connect-src 'self'"));
            assert!(!csp.contains("http:") && !csp.contains("https:") && !csp.contains('*'));
            assert_eq!(h[header::X_CONTENT_TYPE_OPTIONS], "nosniff");
        }
    }

    #[tokio::test]
    async fn classic_page_is_gone() {
        let d = face_dir();
        let e = env_face(Some(d.path().to_path_buf()));
        for uri in ["/classic", "/app.js", "/app.css"] {
            assert_eq!(
                raw(&e, req("GET", uri, None)).await.0,
                StatusCode::NOT_FOUND
            );
        }
    }

    #[tokio::test]
    async fn plain_notice_without_a_face() {
        // An empty EYE_FACE_DIR has no index.html.
        let empty = tempfile::tempdir().unwrap();
        let e = env_face(Some(empty.path().to_path_buf()));
        let (st, _, body) = raw(&e, req("GET", "/", None)).await;
        assert_eq!(st, StatusCode::OK);
        assert!(body.contains("not built into this binary") && body.contains("npm run build"));
        // No EYE_FACE_DIR: the embedded table, which is empty unless face/dist was built.
        let e = env_face(None);
        let (st, _, body) = raw(&e, req("GET", "/", None)).await;
        assert_eq!(st, StatusCode::OK);
        assert_eq!(
            body.contains("not built into this binary"),
            FACE_FILES.is_empty()
        );
    }

    #[tokio::test]
    async fn app_icons_need_no_token_and_the_manifest_logs_in() {
        let d = face_dir();
        std::fs::write(d.path().join("favicon.svg"), "<svg/>").unwrap();
        let e = env_face(Some(d.path().to_path_buf()));
        let bare = |uri: &str| {
            Request::builder()
                .uri(uri)
                .header("host", "127.0.0.1:7420")
                .body(Body::empty())
                .unwrap()
        };
        assert_eq!(raw(&e, bare("/favicon.svg")).await.0, StatusCode::OK);
        for uri in [
            "/",
            "/assets/app-abc123.js",
            "/api/board",
            "/secret.txt",
            "/manifest.webmanifest",
        ] {
            assert_eq!(
                raw(&e, bare(uri)).await.0,
                StatusCode::UNAUTHORIZED,
                "{uri}"
            );
        }
        // With the token, the manifest's start URL carries it, so the installed app logs itself in.
        let (st, h, body) = raw(&e, req("GET", "/manifest.webmanifest", None)).await;
        assert_eq!(st, StatusCode::OK);
        assert_eq!(h[header::CONTENT_TYPE], "application/manifest+json");
        let m: Value = serde_json::from_str(&body).unwrap();
        assert_eq!(m["start_url"], format!("/?t={TOKEN}"));
        // The token link's cookie lasts a year.
        let (_, h, _) = raw(&e, bare(&format!("/?t={TOKEN}"))).await;
        assert!(h[header::SET_COOKIE]
            .to_str()
            .unwrap()
            .contains("Max-Age=31536000"));
    }

    #[tokio::test]
    async fn face_dir_does_not_leak_outside_files() {
        let d = face_dir();
        let sub = d.path().join("assets");
        let e = env_face(Some(sub));
        for uri in [
            "/assets/../secret.txt",
            "/%2e%2e/secret.txt",
            "/..%2fsecret.txt",
            "//secret.txt",
        ] {
            let (st, _, body) = raw(&e, req("GET", uri, None)).await;
            assert!(!body.contains("outside"), "{uri}");
            assert_ne!(st, StatusCode::OK, "{uri}");
        }
    }
}
